head.script:
scwin.createWindowTest = function(title) {
    wc1.createWindow(title, "", "windowContainer_WPFF-332_(WSQ-3820)_sub_auto.xml", "windowTitle", "windowId", "selectWindow", null, null, null, null, "wframe");
};
scwin.unitTest = function() {
    //Unit
    WebSquare.wUnit.start();
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getDomById($p.id+'wc1_subWindow0_wframe_wframe1_trigger1').click()");
    WebSquare.wUnit.addCommand("pause", "1000");
    WebSquare.wUnit.addCommand("assert", "localStorage.getItem('log') != null", "true");
    WebSquare.wUnit.addCommand("pause", "500");
    //Run test and stop
    WebSquare.wUnit.run();
    WebSquare.wUnit.stop();
}
scwin.onpageload2 = function() {
    if (typeof scwin.onpageload === "function") {
        scwin.onpageload();
    }
    requires("uiplugin.popup");
    scwin.createWindowTest("aaa");
    localStorage.removeItem("log");
    if (typeof scwin.unitTest === "function") {
        scwin.unitTest();
    }
}
